ctivate':'Deactivate'; ?></button></form></article><?php endforeach; ?></div></section><section class="w-panel"><h2>Customer accounts</h2><div class="w-list"><?php foreach($users as $u): ?><article class="w-row"><div><strong><?php echo html_escape($u['first_name'].' '.$u['last_name']); ?></strong><small><?php echo html_escape($u['email'].' · '.$u['username']); ?></small></div><?php echo form_open('system/toggle_user',array('class'=>'w-inline')); ?><input type="hidden" name="id" value="<?php echo (int)$u['id']; ?>"><input type="hidden" name="kind" value="customer"><button class="w-button-light"><?php echo empty($u['is_active'])?'Reactivate':'Deactivate'; ?></button></form></article><?php endforeach; ?></div></section>
