<script>(function(){document.querySelectorAll('.checkin').forEach(function(button){button.addEventListener('click',function(){var form=button.closest('form');var send=function(lat,lng){form.querySelector('[name=latitude]').value=lat||'';form.querySelector('[name=longitude]').value=lng||'';form.submit();};if(navigator.geolocation){navigator.geolocation.getCurrentPosition(function(p){send(p.coords.latitude,p.coords.longitude);},function(){send('', '');},{timeout:7000});}else{send('', '');}});});})();</script></body></html>
